export function canvasDropWorldPoint(client: {x:number;y:number}, rect: {left:number;top:number;width:number;height:number}, size:{width:number;height:number}, camera:CanvasViewport) {
  if (![rect.width,rect.height,size.width,size.height].every(value=>Number.isFinite(value)&&value>0)) throw Error('Canvas drop target is unavailable')
  return viewportToWorld({x:(client.x-rect.left)*size.width/rect.width,y:(client.y-rect.top)*size.height/rect.height},camera)
}
export function dropEvidenceOnCanvas(workspace:Pick<NotebookWorkspace,'paperId'|'addOwnedImage'>, transfer:DataTransfer, point:{x:number;y:number}):Promise<boolean> {
  const payload=readEvidenceDrag(transfer,workspace.paperId??'')
  if(!payload)return Promise.resolve(false)
  return workspace.addOwnedImage(payload.assetId,point).then(()=>true)
}
